import { useCallback, useEffect, useRef, useState } from "react";

type DragModifierKey = "Cmd" | "Shift" | "Alt";

/** The modifier flags we read off a keyboard or mouse event. */
type ModifierState = { metaKey: boolean; ctrlKey: boolean; shiftKey: boolean; altKey: boolean };

type UseDragScrollOptions = {
  /** Turn drag-scrolling off entirely. */
  disabled?: boolean;
  /** Gate: drag only works while this key is held. Absent means always on. */
  enableModifierKey?: DragModifierKey;
  /** Legacy gate: drag is skipped while this key is held. */
  disableModifierKey?: DragModifierKey;
};

// "Cmd" means the platform's primary command key: Cmd on Apple, Ctrl elsewhere. Resolved once so
// callers stay platform-agnostic. Ctrl is not accepted on Apple, where Ctrl+click is a right-click.
const IS_APPLE_PLATFORM =
  typeof navigator !== "undefined" &&
  /Mac|iPhone|iPad|iPod/i.test(
    (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData?.platform ??
      navigator.platform ??
      navigator.userAgent
  );

/** Is the given modifier key currently held? */
const isModifierKeyDown = (key: DragModifierKey, mods: ModifierState) => {
  switch (key) {
    case "Cmd":
      return IS_APPLE_PLATFORM ? mods.metaKey : mods.ctrlKey;
    case "Shift":
      return mods.shiftKey;
    case "Alt":
      return mods.altKey;
  }
};

type UseDragScrollResult<T> = {
  /** Spread onto the scrollable element. `ref` must land on that same element. */
  eventHandlers: {
    onMouseDown: (e: React.MouseEvent) => void;
    onTouchStart: (e: React.TouchEvent) => void;
    ref: React.RefObject<T | null>;
  };
  /** Can the user drag right now? Drives cursor css and any "hold X to drag" helper. */
  isDragScrollEnabled: boolean;
  /** A drag is in progress. */
  isDragging: boolean;
  /** Content is larger than the element, so there is somewhere to scroll. */
  isOverflowing: boolean;
  /** This mousedown was skipped because a modifier gate blocked it. */
